INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),69,9,'وجاء الطاغية فرعون، ومَن سبقه من الأمم التي كفرت برسلها، وأهل قرى قوم لوط الذين انقلبت بهم ديارهم بسبب الفعلة المنكرة من الكفر والشرك والفواحش، فعصت كل أمة منهم رسول ربهم الذي أرسله إليهم، فأخذهم الله أخذة بالغة في الشدة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/69/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=69) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),69,10,'وجاء الطاغية فرعون، ومَن سبقه من الأمم التي كفرت برسلها، وأهل قرى قوم لوط الذين انقلبت بهم ديارهم بسبب الفعلة المنكرة من الكفر والشرك والفواحش، فعصت كل أمة منهم رسول ربهم الذي أرسله إليهم، فأخذهم الله أخذة بالغة في الشدة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/69/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=69) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),69,11,'إنَّا لما جاوز الماء حدَّه، حتى علا وارتفع فوق كل شيء، حملنا أصولكم مع نوح في السفينة التي تجري في الماء؛ لنجعل الواقعة التي كان فيها نجاة المؤمنين وإغراق الكافرين عبرة وعظة، وتحفظها كل أذن مِن شأنها أن تحفظ، وتعقل عن الله ما سمعت.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/69/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=69) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),69,12,'إنَّا لما جاوز الماء حدَّه، حتى علا وارتفع فوق كل شيء، حملنا أصولكم مع نوح في السفينة التي تجري في الماء؛ لنجعل الواقعة التي كان فيها نجاة المؤمنين وإغراق الكافرين عبرة وعظة، وتحفظها كل أذن مِن شأنها أن تحفظ، وتعقل عن الله ما سمعت.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/69/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=69) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),69,13,'فإذا نفخ المَلَك في "القرن" نفخة واحدة، وهي النفخة الأولى التي يكون عندها هلاك العالم، ورُفعت الأرض والجبال عن أماكنها فكُسِّرتا، ودُقَّتا دقة واحدة. ففي ذلك الحين قامت القيامة، وانصدعت السماء، فهي يومئذ ضعيفة مسترخية، لا تماسُك فيها ولا صلابة، والملائكة على جوانبها وأطرافها، ويحمل عرش ربك فوقهم يوم القيامة ثمانية من الملائكة العظام. في ذلك اليوم تُعرضون على الله- أيها الناس- للحساب والجزاء، لا يخفى عليه شيء من أسراركم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/69/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=69) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
