INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),69,19,'فأمَّا من أُعطي كتاب أعماله بيمينه، فيقول ابتهاجًا وسرورًا: خذوا اقرؤوا كتابي، إني أيقنت في الدنيا بأني سألقى جزائي يوم القيامة، فأعددت له العدة من الإيمان والعمل الصالح، فهو في عيشة هنيئة مرضية، في جنة مرتفعة المكان والدرجات، ثمارها قريبة يتناولها القائم والقاعد والمضطجع. يقال لهم: كلوا أكلا واشربوا شربًا بعيدًا عن كل أذى، سالمين من كل مكروه؛ بسبب ما قدَّمتم من الأعمال الصالحة في أيام الدنيا الماضية.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/69/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=69) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),69,20,'فأمَّا من أُعطي كتاب أعماله بيمينه، فيقول ابتهاجًا وسرورًا: خذوا اقرؤوا كتابي، إني أيقنت في الدنيا بأني سألقى جزائي يوم القيامة، فأعددت له العدة من الإيمان والعمل الصالح، فهو في عيشة هنيئة مرضية، في جنة مرتفعة المكان والدرجات، ثمارها قريبة يتناولها القائم والقاعد والمضطجع. يقال لهم: كلوا أكلا واشربوا شربًا بعيدًا عن كل أذى، سالمين من كل مكروه؛ بسبب ما قدَّمتم من الأعمال الصالحة في أيام الدنيا الماضية.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/69/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=69) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
