INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),69,25,'وَأمَّا من أعطي كتاب أعماله بشماله، فيقول نادمًا متحسرًا: يا ليتني لم أُعط كتابي، ولم أعلم ما جزائي؟ يا ليت الموتة التي متُّها في الدنيا كانت القاطعة لأمري، ولم أُبعث بعدها، ما نفعني مالي الذي جمعته في الدنيا، ذهبت عني حجتي، ولم يَعُدْ لي حجة أحتج بها.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/69/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=69) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
