INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),69,38,'فلا أقسم بما تبصرون من المرئيات، وما لا تبصرون مما غاب عنكم، إن القرآن لَكَلام الله، يتلوه رسول عظيم الشرف والفضل، وليس بقول شاعر كما تزعمون، قليلا ما تؤمنون، وليس بسجع كسجع الكهان، قليلا ما يكون منكم تذكُّر وتأمُّل للفرق بينهما، ولكنه كلام رب العالمين الذي أنزله على رسوله محمد صلى الله عليه وسلم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/69/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=69) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
