INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),69,44,'ولو ادَّعى محمد علينا شيئًا لم نقله، لانتقمنا وأخذنا منه باليمين، ثم لقطعنا منه نياط قلبه، فلا يقدر أحد منكم أن يحجز عنه عقابنا. إن هذا القرآن لعظة للمتقين الذين يمتثلون أوامر الله ويجتنبون نواهيه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/69/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=69) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
