INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),70,15,'ليس الأمر كما تتمناه- أيها الكافر- من الافتداء، إنها جهنم تتلظى نارها وتلتهب، تنزع بشدة حرها جلدة الرأس وسائر أطراف البدن، تنادي مَن أعرض عن الحق في الدنيا، وترك طاعة الله ورسوله، وجمع المال، فوضعه في خزائنه، ولم يؤدِّ حق الله فيه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/70/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=70) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
