INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),70,30,'إن الإنسان جُبِلَ على الجزع وشدة الحرص، إذا أصابه المكروه والعسر فهو كثير الجزع والأسى، وإذا أصابه الخير واليسر فهو كثير المنع والإمساك، إلا المقيمين للصلاة الذين يحافظون على أدائها في جميع الأوقات، ولا يَشْغَلهم عنها شاغل، والذين في أموالهم نصيب معيَّن فرضه الله عليهم، وهو الزكاة لمن يسألهم المعونة، ولمن يتعفف عن سؤالها، والذين يؤمنون بيوم الحساب والجزاء فيستعدون له بالأعمال الصالحة، والذين هم خائفون من عذاب الله. إن عذاب ربهم لا ينبغي أن يأمنه أحد. والذين هم حافظون لفروجهم عن كل ما حرَّم الله عليهم، إلا على أزواجهم وإمائهم، فإنهم غير مؤاخذين.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/70/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=70) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),70,31,'فمن طلب لقضاء شهوته غير الزوجات والمملوكات، فأولئك هم المتجاوزون الحلال إلى الحرام. والذين هم حافظون لأمانات الله، وأمانات العباد، وحافظون لعهودهم مع الله تعالى ومع العباد، والذين يؤدُّون شهاداتهم بالحق دون تغيير أو كتمان، والذين يحافظون على أداء الصلاة ولا يخلُّون بشيء من واجباتها. أولئك المتصفون بتلك الأوصاف الجليلة مستقرُّون في جنات النعيم، مكرمون فيها بكل أنواع التكريم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/70/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=70) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
