INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),70,36,'فأيُّ دافع دفع هؤلاء الكفرة إلى أن يسيروا نحوك -أيها الرسول- مسرعين، وقد مدُّوا أعناقهم إليك مقبلين بأبصارهم عليك، يتجمعون عن يمينك وعن شمالك حلقًا متعددة وجماعات متفرقة يتحدثون ويتعجبون؟ أيطمع كل واحد من هؤلاء الكفار أن يدخله الله جنة النعيم الدائم؟ ليس الأمر كما يطمعون، فإنهم لا يدخلونها أبدًا. إنَّا خلقناهم مما يعلمون مِن ماء مهين كغيرهم، فلم يؤمنوا، فمن أين يتشرفون بدخول جنة النعيم؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/70/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=70) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
