INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),74,38,'كل نفس بما كسبت من أعمال الشر والسوء محبوسة مرهونة بكسبها، لا تُفَكُّ حتى تؤدي ما عليها من الحقوق والعقوبات، إلا المسلمين المخلصين أصحاب اليمين الذين فكُّوا رقابهم بالطاعة، هم في جنات لا يُدْرَك وصفها، يسأل بعضهم بعضًا عن الكافرين الذين أجرموا في حق أنفسهم: ما الذي أدخلكم جهنم، وجعلكم تذوقون سعيرها؟ قال المجرمون: لم نكن من المصلِّين في الدنيا، ولم نكن نتصدق ونحسن للفقراء والمساكين، وكنا نتحدث بالباطل مع أهل الغَواية والضلالة، وكنا نكذب بيوم الحساب والجزاء، حتى جاءنا الموت، ونحن في تلك الضلالات والمنكرات.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/74/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=74) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
